export function localAiSetupLabels(language='EN'){
 const r=localAiSetupCopy[language]||localAiSetupCopy.EN;
 return Object.fromEntries(['title','checking','offline','empty','textOnly','unverified','ready','installStep','modelStep','refreshStep','download','copy','copied','copyFailed','retry','privacy','modelLink','memory'].map((key,i)=>[key,r[i]]));
}
export function localAiSetupState({inventory=[],vision=false,offline=false,loading=false,capability=()=>null}={}){
 if(loading)return 'checking';if(offline)return 'offline';if(!inventory.length)return 'empty';
 if(!vision||inventory.some(item=>capability(item)===true))return 'ready';
 return inventory.some(item=>capability(item)===null)?'unverified':'textOnly';
}
export function attachLocalAiSetup({host,getLanguage,onRetry=()=>{}}){
 const make=tag=>document.createElement(tag),root=make('details'),summary=make('summary'),status=make('p'),steps=make('ol'),install=make('li'),model=make('li'),refresh=make('li'),installText=make('p'),modelText=make('p'),download=make('a'),modelLink=make('a'),command=make('code'),actions=make('div'),copy=make('button'),retry=make('button'),message=make('p'),privacy=make('p'),memory=make('p');
 root.className='local-ai-setup';download.href='https://ollama.com/download/windows';modelLink.href='https://ollama.com/library/gemma3:4b';
 for(const link of [download,modelLink]){link.target='_blank';link.rel='noopener noreferrer';}
 status.setAttribute('role','status');status.setAttribute('aria-live','polite');message.setAttribute('role','status');
 copy.type='button';retry.type='button';actions.className='local-ai-setup-actions';command.textContent=LOCAL_AI_STARTER_COMMAND;
 install.append(installText,download);model.append(modelText,command,modelLink);steps.append(install,model,refresh);actions.append(copy,retry);root.append(summary,status,steps,actions,message,privacy,memory);host.append(root);
 let previousState=null;
 function update(state){const w=localAiSetupLabels(getLanguage());summary.textContent=w.title;status.textContent=w[state]||w.offline;installText.textContent=w.installStep;modelText.textContent=w.modelStep;refresh.textContent=w.refreshStep;download.textContent=w.download;modelLink.textContent=w.modelLink;copy.textContent=w.copy;retry.textContent=w.retry;privacy.textContent=w.privacy;memory.textContent=w.memory;retry.disabled=state==='checking';
  if(previousState!==state)root.open=state!=='ready';previousState=state;return status.textContent;
 }
 copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(LOCAL_AI_STARTER_COMMAND);message.textContent=localAiSetupLabels(getLanguage()).copied;}catch{message.textContent=localAiSetupLabels(getLanguage()).copyFailed;}});
 retry.addEventListener('click',()=>{if(!retry.disabled)return onRetry();});update('checking');
 return {root,update,text:()=>status.textContent,state:()=>previousState};
}
